const TEST = new RegExp(RE.source);
const SKIP = new Set(['SCRIPT', 'STYLE', 'TEXTAREA', 'OPTION', 'INPUT', 'SVG', 'TITLE']);

function weightFor(el, ch) {
  if (SOLID.includes(ch)) return 'f';
  return el && el.closest && el.closest('.ic, .hi, .tile, .big') ? 'd' : 'r';
}

